import React, { useEffect, useState } from 'react';
import api from '../api/axios';
import { Container, Table, Form, Button } from 'react-bootstrap';

const Schedule = () => {
  const [schedule, setSchedule] = useState([]);
  const [note, setNote] = useState('');

  useEffect(() => {
    const fetchSchedule = async () => {
      const res = await api.get('/schedule'); // маршрут
      setSchedule(res.data);
    };
    fetchSchedule();
  }, []);

  return (
    <Container className="mt-4">
      <h3 style={{ textAlign: 'center' }}>Месяц: Март 2026</h3>
      <Table striped bordered hover>
        <thead>
          <tr>
            <th>№</th>
            <th>День недели</th>
            <th>Предмет</th>
            <th>Домашнее задание</th>
            <th>Оценка</th>
          </tr>
        </thead>
        <tbody>
          {schedule.map(item => (
            <tr key={item.id}>
              <td>{item.lesson_number}</td>
              <td>{item.day_of_week} ({item.date})</td>
              <td>{item.subject_name}</td>
              <td>{item.homework}</td>
              <td>{item.grade || '—'}</td>
            </tr>
          ))}
        </tbody>
      </Table>
      <h5>Заметки</h5>
      <Form.Group>
        <Form.Control as="textarea" rows={3} value={note} onChange={e => setNote(e.target.value)} />
      </Form.Group>
      <Button className="mt-2">Сохранить заметку</Button>
    </Container>
  );
};

export default Schedule;
